import AccessorArray = require( '@stdlib/array/base/accessor' );
import gsearchSorted = require( './index' );


// TESTS //

// The function returns a collection...
{
	const x = new Float64Array( 10 );
	const search = new Float64Array( 10 );
	const out = new Int32Array( 10 );

	gsearchSorted( x.length, search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectType Int32Array
	gsearchSorted( x.length, search.length, 'right', new AccessorArray( x ), 1, new AccessorArray( search ), 1, new AccessorArray( out ), 1 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float64Array( 10 );
	const search = new Float64Array( 10 );
	const out = new Int32Array( 10 );

	gsearchSorted( '10', search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectError
	gsearchSorted( true, search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectError
	gsearchSorted( false, search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectError
	gsearchSorted( null, search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectError
	gsearchSorted( undefined, search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectError
	gsearchSorted( [], search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectError
	gsearchSorted( {}, search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectError
	gsearchSorted( ( x: number ): number => x, search.length, 'left', x, 1, search, 1, out, 1 ); // $ExpectError
}

